// Renders the Homebrew formula for `infraone` (IO-18385, I6) from a release's
// SHA256SUMS: one prebuilt binary per platform, downloaded from the public
// releases repository, so `brew install` needs neither Node nor npm.
//
//   node packaging/homebrew/render-formula.mjs <version> <owner/repo> <SHA256SUMS> > Formula/infraone.rb
//
// The binaries are attached to the release `infraone-v<version>` of
// <owner/repo>, named infraone-<os>-<arch> (packaging/binary/build.mjs).
//
// One formula, one download, one binary (CLI-165): `infraone`. `harness` and
// `operator` are two-line scripts written next to it that run `infraone
// harness` and `infraone operator`, the mounts inside that binary, so they
// always match the installed version and need no formula of their own. Under
// them the words a program says follow the mount (`infraone harness …`), as
// they do for anyone typing the long form; the npm package's aliases keep the
// short names in their output because each has a bin file of its own.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** The aliases installed beside `infraone`: each runs `infraone <name>`. */
export const ALIASES = ["harness", "operator"];

/**
 * The formulas this one replaces. Taking them out of the tap uninstalls nothing, so a
 * machine that has one still has its keg linked at bin/harness or bin/operator, where this
 * formula's aliases go. `conflicts_with` makes brew stop before linking, naming it.
 */
export const RETIRED_FORMULAS = ["harness", "operator", "harness-cli"];

export const PLATFORMS = [
  { os: "macos", cpu: "arm", target: "darwin-arm64" },
  { os: "macos", cpu: "intel", target: "darwin-x64" },
  { os: "linux", cpu: "arm", target: "linux-arm64" },
  { os: "linux", cpu: "intel", target: "linux-x64" },
];

/** `{target: sha256}` from a SHA256SUMS file's text. */
export function parseSums(text) {
  const sums = {};
  for (const line of text.split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "") continue;
    const match = /^([0-9a-f]{64}) [ *]infraone-([a-z0-9]+-[a-z0-9]+)$/.exec(trimmed);
    if (match === null) throw new Error(`not a SHA256SUMS line: ${JSON.stringify(trimmed)}`);
    sums[match[2]] = match[1];
  }
  return sums;
}

/** The formula's Ruby source. Every platform must have a checksum. */
export function renderFormula({ version, repo, sums }) {
  if (!/^\d+\.\d+\.\d+(-[0-9A-Za-z.]+)?$/.test(version)) throw new Error(`not a release version: ${JSON.stringify(version)}`);
  if (!/^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/.test(repo)) throw new Error(`not an owner/repo: ${JSON.stringify(repo)}`);
  const base = `https://github.com/${repo}/releases/download/infraone-v${version}`;

  const block = (os) =>
    PLATFORMS.filter((platform) => platform.os === os)
      .map(({ cpu, target }) => {
        const sha = sums[target];
        if (sha === undefined) throw new Error(`SHA256SUMS has no infraone-${target}`);
        return [
          `    on_${cpu} do`,
          `      url "${base}/infraone-${target}"`,
          `      sha256 "${sha}"`,
          "",
          "      def install",
          `        bin.install "infraone-${target}" => "infraone"`,
          "        install_aliases",
          "      end",
          "    end",
        ].join("\n");
      })
      .join("\n");

  const aliasScripts = ALIASES.map((name) =>
    [
      `    (bin/"${name}").write <<~SH`,
      "      #!/bin/sh",
      `      exec "#{bin}/infraone" ${name} "$@"`,
      "    SH",
    ].join("\n"),
  ).join("\n");
  const conflicts = RETIRED_FORMULAS.map(
    (name) => `  conflicts_with "${name}", because: "infraone installs its own harness and operator commands; run brew uninstall ${name} first"`,
  ).join("\n");
  const aliasPaths = ALIASES.map((name) => `bin/"${name}"`).join(", ");
  // --help, not version: a brew test may run offline, and help needs no server.
  const aliasTests = ALIASES.map((name) => `    assert_match "infraone ${name}", shell_output("#{bin}/${name} --help")`).join("\n");

  return `# Generated by packaging/homebrew/render-formula.mjs for infraone ${version}; do not edit.
class Infraone < Formula
  desc "Infra One from the terminal: your data rooms, with exactly your app rights"
  homepage "https://www.npmjs.com/package/@allocator-one/infraone"
  version "${version}"
  license "MIT"

${conflicts}

  on_macos do
${block("macos")}
  end

  on_linux do
${block("linux")}
  end

  # harness and operator: aliases for \`infraone harness\` and \`infraone operator\`.
  def install_aliases
${aliasScripts}
    chmod 0555, [${aliasPaths}]
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/infraone version")
${aliasTests}
  end
end
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const [version, repo, sumsPath] = process.argv.slice(2);
  if (version === undefined || repo === undefined || sumsPath === undefined) {
    console.error("usage: render-formula.mjs <version> <owner/repo> <SHA256SUMS>");
    process.exit(2);
  }
  try {
    process.stdout.write(renderFormula({ version, repo, sums: parseSums(readFileSync(sumsPath, "utf8")) }));
  } catch (error) {
    console.error(`render-formula: ${error instanceof Error ? error.message : String(error)}`);
    process.exit(1);
  }
}
